{
  "findings": [
    {
      "check_id": "CKV_AWS_261",
      "title": "Ensure HTTP HTTPS Target group defines Healthcheck",
      "resource": "aws_alb_target_group.pass",
      "severity": "MEDIUM",
      "explanation": "The target group does not define a health check configuration. Without a health check, the ALB cannot determine the health of targets, which may lead to routing traffic to unhealthy instances."
    }
  ],
  "patched_code": "resource "aws_alb_target_group" "pass" {
  name     = "tf-example-lb-nlb-tg"
  port     = 25
  protocol = "TCP"
  vpc_id   = aws_vpc.main.id

  health_check {
    interval            = 30
    path                = "/"
    protocol            = "TCP"
    timeout             = 5
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  target_health_state {
    enable_unhealthy_connection_termination = false
  }
}
",
  "fix_summary": "Added a health check configuration to the target group to ensure proper monitoring of target health."
}
